#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
#include "lodepng.h"
#include "cJSON.h"

static std::vector<std::vector<double>> readMatrix(const cJSON* obj, const char* key, int& rows, int& cols){
    const cJSON* arr = cJSON_GetObjectItemCaseSensitive(obj, key);
    rows = cJSON_GetArraySize(arr);
    cols = rows>0 ? cJSON_GetArraySize(cJSON_GetArrayItem(arr,0)) : 0;
    std::vector<std::vector<double>> m(rows, std::vector<double>(cols,0.0));
    for(int i=0;i<rows;i++){
        const cJSON* row = cJSON_GetArrayItem(arr,i);
        for(int j=0;j<cols;j++){
            const cJSON* c = cJSON_GetArrayItem(row,j);
            m[i][j]=cJSON_GetNumberValue(c);
        }
    }
    return m;
}

static std::vector<double> readVec(const cJSON* obj, const char* key, int& n){
    const cJSON* arr = cJSON_GetObjectItemCaseSensitive(obj, key);
    n = cJSON_GetArraySize(arr);
    std::vector<double> v(n,0.0);
    for(int i=0;i<n;i++) v[i]=cJSON_GetNumberValue(cJSON_GetArrayItem(arr,i));
    return v;
}

struct Layer{ std::vector<std::vector<double>> W; std::vector<double> b; };

int main(int argc, char** argv){
    if(argc<3){ fprintf(stderr,"usage: %s weights.json image.png\n",argv[0]); return 1; }
    // read json file
    FILE* f=fopen(argv[1],"rb"); if(!f){fprintf(stderr,"open %s failed\n",argv[1]);return 1;}
    fseek(f,0,SEEK_END); long len=ftell(f); fseek(f,0,SEEK_SET);
    std::string data(len,'\0'); fread(&data[0],1,len,f); fclose(f);
    cJSON* root=cJSON_Parse(data.c_str()); if(!root){fprintf(stderr,"json parse failed\n");return 1;}
    double scale=cJSON_GetNumberValue(cJSON_GetObjectItem(root,"pixel_scale"));
    double offset=cJSON_GetNumberValue(cJSON_GetObjectItem(root,"pixel_offset"));
    const cJSON* layers=cJSON_GetObjectItem(root,"layers");
    int nl=cJSON_GetArraySize(layers);
    std::vector<Layer> Ls(nl);
    for(int li=0; li<nl; li++){
        const cJSON* lo=cJSON_GetArrayItem(layers,li);
        int r,c;
        Ls[li].W=readMatrix(lo,"weight",r,c);
        int bn;
        Ls[li].b=readVec(lo,"bias",bn);
    }
    // decode png
    unsigned char* img=0; unsigned w=0,h=0;
    unsigned err=lodepng_decode32_file(&img,&w,&h,argv[2]);
    if(err){fprintf(stderr,"png decode err %u\n",err);return 1;}
    int n=w*h;
    std::vector<double> x(n);
    for(int i=0;i<n;i++){ x[i]=( (double)img[4*i]) * scale + offset; } // R channel (grayscale)
    free(img);
    // forward
    std::vector<double> v(x);
    for(int li=0; li<nl; li++){
        int R=Ls[li].W.size(); int C=Ls[li].W[0].size();
        std::vector<double> o(R,0.0);
        for(int i=0;i<R;i++){
            double s=Ls[li].b[i];
            for(int j=0;j<C;j++) s+=Ls[li].W[i][j]*v[j];
            o[i]=s;
        }
        if(li<nl-1){ for(auto& z:o) if(z<0) z=0; } // ReLU
        v=o;
    }
    int best=0;
    for(int i=1;i<(int)v.size();i++) if(v[i]>v[best]) best=i;
    printf("%d\n", best);
    cJSON_Delete(root);
    return 0;
}
